// === TEXTO ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};

console.log('[TEXT] chatId:', data.chatId);
console.log('[TEXT] message:', data.body);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: data.body || '',
    inputType: 'text'
  }
};

// === ÁUDIO ===
// O áudio JÁ VEM em base64 no webhook, não precisa baixar!
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const media = data.media || {};

if (!media.data) {
  console.log('[AUDIO] Erro: media.data não encontrado');
  return {
    json: {
      skip: true,
      reason: 'media.data ausente'
    }
  };
}

// Converter base64 → Buffer → Binary
const audioBase64 = media.data;
const audioBuffer = Buffer.from(audioBase64, 'base64');

console.log('[AUDIO] Audio base64 length:', audioBase64.length);
console.log('[AUDIO] Audio buffer length:', audioBuffer.length);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    inputType: 'voice'
  },
  binary: {
    data: {
      data: audioBuffer.toString('base64'),
      mimeType: media.mimetype || 'audio/ogg',
      fileName: 'audio.ogg'
    }
  }
};

// === ÁUDIO TRANSCRITO ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const transcription = $json.text || '';

console.log('[AUDIO] Transcription:', transcription);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[🎤 ÁUDIO TRANSCRITO]\n${transcription}`,
    inputType: 'voice'
  }
};

// === IMAGEM ===
// A imagem JÁ VEM em base64 no webhook, não precisa baixar!
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const media = data.media || {};

if (!media.data) {
  console.log('[IMAGE] Erro: media.data não encontrado');
  return {
    json: {
      skip: true,
      reason: 'media.data ausente'
    }
  };
}

// Remover prefixo data:image se existir
let imageBase64 = media.data;
if (imageBase64.includes(',')) {
  imageBase64 = imageBase64.split(',')[1];
}

console.log('[IMAGE] Base64 length:', imageBase64.length);

// Criar estrutura binary para o Vision node
const imageBuffer = Buffer.from(imageBase64, 'base64');

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    caption: data.caption || 'Descreva esta imagem em detalhes',
    inputType: 'image'
  },
  binary: {
    data: {
      data: imageBuffer.toString('base64'),
      mimeType: media.mimetype || 'image/jpeg',
      fileName: 'image.jpg'
    }
  }
};

// === IMAGEM ANALISADA ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const visionResult = $json.content || '';

console.log('[IMAGE] Vision result:', visionResult);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[📷 IMAGEM]\nAnálise:\n${visionResult}`,
    inputType: 'image'
  }
};

// === DOCUMENTO ===
// O PDF JÁ VEM em base64 no webhook, não precisa baixar!
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const media = data.media || {};

if (!media.data) {
  console.log('[DOCUMENT] Erro: media.data não encontrado');
  return {
    json: {
      skip: true,
      reason: 'media.data ausente'
    }
  };
}

// ✅ FIX: Verificar mimetype em media.mimetype (não data.mimetype)
if (media.mimetype !== 'application/pdf') {
  console.log('[DOCUMENT] Não é PDF:', media.mimetype);
  return {
    json: {
      chatId: data.chatId,
      from: data.from,
      messageId: data.id,
      notPdf: true,
      mimetype: media.mimetype
    }
  };
}

// Converter base64 → Buffer → Binary
const pdfBase64 = media.data;
const pdfBuffer = Buffer.from(pdfBase64, 'base64');

console.log('[DOCUMENT] PDF base64 length:', pdfBase64.length);
console.log('[DOCUMENT] PDF buffer length:', pdfBuffer.length);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    filename: data.body || media.filename || 'document.pdf',
    inputType: 'document'
  },
  binary: {
    data: {
      data: pdfBuffer.toString('base64'),
      mimeType: 'application/pdf',
      fileName: data.body || media.filename || 'document.pdf'
    }
  }
};

// === PDF EXTRAÍDO ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};
const pdfText = $json.text || '';

console.log('[DOCUMENT] PDF text length:', pdfText.length);

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[📄 DOCUMENTO PDF]\nConteúdo:\n${pdfText.substring(0, 3000)}...`,
    inputType: 'document'
  }
};

// === REJEITAR NÃO-PDF ===
const body = $('Webhook OpenWA').item.json.body;
const data = body.data || {};

return {
  json: {
    chatId: data.chatId,
    from: data.from,
    messageId: data.id,
    text: `[❌ DOCUMENTO NÃO SUPORTADO]\nTipo: ${$json.mimetype || 'desconhecido'}\n\nPor favor, envie apenas arquivos PDF.`,
    inputType: 'document'
  }
};

// =================================================================
// 🔒 SANITIZAÇÃO DE SEGURANÇA + LIMPEZA DE RESPOSTA
// =================================================================
const llmOutput = $input.first().json;
let text = llmOutput.text || llmOutput.output || '';

console.log('[CLEAN] ===== INICIO =====');
console.log('[CLEAN] Raw LLM output length:', text.length);
console.log('[CLEAN] First 200 chars:', text.substring(0, 200));

const originalLength = text.length;
let redactionCount = 0;
const redactedTypes = [];

// === STEP 1: Remover tags de raciocínio interno ===
if (text.includes('<think>')) {
  console.log('[SECURITY] Found <think> tag, removing...');
  const lastCloseTag = text.lastIndexOf('</think>');
  if (lastCloseTag !== -1) {
    text = text.substring(lastCloseTag + 8);
  }
  text = text.replace(/<think>[\s\S]*?<\/think>/g, '');
  text = text.trim().replace(/^\n+/, '');
  redactionCount++;
  redactedTypes.push('THINKING_TAGS');
}

// === STEP 2: Detectar contexto sensível ===
const sensitiveKeywords = [
  'cpf', 'cnpj', 'rg', 'cnh', 'renavam', 'placa',
  'documento', 'protocolo', 'certidão'
];
const lowerText = text.toLowerCase();
const hasSensitiveContext = sensitiveKeywords.some(kw => lowerText.includes(kw));

if (hasSensitiveContext) {
  console.log('[SECURITY] Sensitive context detected, applying PII redaction...');

  // === STEP 3: Redactar dados sensíveis (PII) ===
  const piiPatterns = [
    // CPF: 000.000.000-00 ou 00000000000
    { pattern: /\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/g, replacement: '[CPF REDACTED]', name: 'CPF' },
    { pattern: /\bCPF:?\s*\d{11}\b/gi, replacement: 'CPF: [REDACTED]', name: 'CPF' },

    // CNPJ: 00.000.000/0000-00 ou 00000000000000
    { pattern: /\b\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}\b/g, replacement: '[CNPJ REDACTED]', name: 'CNPJ' },
    { pattern: /\bCNPJ:?\s*\d{14}\b/gi, replacement: 'CNPJ: [REDACTED]', name: 'CNPJ' },

    // RENAVAM: 11 dígitos
    { pattern: /\bRENAVAM:?\s*\d{11}\b/gi, replacement: 'RENAVAM: [REDACTED]', name: 'RENAVAM' },

    // Placas: ABC1234 ou ABC-1234
    { pattern: /\bPlaca:?\s*[A-Z]{3}[-\s]?\d[A-Z0-9]\d{2}\b/gi, replacement: 'Placa: [REDACTED]', name: 'PLACA' },
    { pattern: /\b[A-Z]{3}[-\s]?\d[A-Z0-9]\d{2}\b/g, replacement: '[PLACA REDACTED]', name: 'PLACA' },

    // Emails
    { pattern: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, replacement: '[EMAIL REDACTED]', name: 'EMAIL' },

    // Telefones: (00) 00000-0000
    { pattern: /\(?\d{2}\)?\s?\d{4,5}-?\d{4}/g, replacement: '[TELEFONE REDACTED]', name: 'TELEFONE' },

    // Valores monetários altos (>= R$ 1.000,00)
    { pattern: /R\$\s*\d{1,3}(?:[.,]\d{3})+[.,]\d{2}/g, replacement: 'R$ [VALOR REDACTED]', name: 'VALOR' },

    // Datas sensíveis (nascimento, documentos)
    { pattern: /\b(?:Nascimento|Data):?\s*\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}\b/gi, replacement: '[DATA REDACTED]', name: 'DATA' },

    // Nomes completos após labels
    { pattern: /\b(Nome|Contribuinte|Proprietário|Titular):?\s*([A-ZÀ-Ú][a-zà-ú]+(?:\s+[A-ZÀ-Ú][a-zà-ú]+){1,5})/gi, 
      replacement: '$1: [NOME REDACTED]', name: 'NOME' }
  ];

  piiPatterns.forEach(({ pattern, replacement, name }) => {
    const matches = text.match(pattern);
    if (matches && matches.length > 0) {
      text = text.replace(pattern, replacement);
      redactionCount += matches.length;
      if (!redactedTypes.includes(name)) {
        redactedTypes.push(name);
      }
      console.log(`[SECURITY] Redacted ${matches.length} ${name}`);
    }
  });
}

// === STEP 4: Limpar formatação ===
text = text
  .replace(/\n{3,}/g, '\n\n')
  .replace(/\s{3,}/g, '  ')
  .trim();

// === STEP 5: Limitar tamanho (WhatsApp limit) ===
if (text.length > 4000) {
  console.log('[CLEAN] Truncating to 4000 chars');
  text = text.substring(0, 3997) + '...';
}

// === STEP 6: Validação final ===
if (!text || text.trim().length === 0) {
  console.error('[CLEAN] ERROR: Text is empty after cleaning!');
  text = 'Desculpa, tive um problema ao processar. Pode repetir?';
}

// === AUDITORIA DE SEGURANÇA ===
if (redactionCount > 0) {
  console.log('[SECURITY] ===== AUDIT REPORT =====');
  console.log('[SECURITY] Redaction count:', redactionCount);
  console.log('[SECURITY] Redacted types:', redactedTypes.join(', '));
  console.log('[SECURITY] Original length:', originalLength);
  console.log('[SECURITY] Final length:', text.length);
  console.log('[SECURITY] Reduction:', originalLength - text.length, 'chars');
  console.log('[SECURITY] ===================================');
}

console.log('[CLEAN] Final text length:', text.length);
console.log('[CLEAN] Final text:', text);
console.log('[CLEAN] ===== FIM =====');

// ✅ Buscar chatId e messageId do WEBHOOK
const webhookData = $('Webhook OpenWA').item.json.body;
const chatId = webhookData.data?.chatId;
const messageId = webhookData.data?.id;

return {
  json: {
    chatId: chatId,
    text: text,
    messageId: messageId,
    _security: {
      sanitized: redactionCount > 0,
      redactionCount: redactionCount,
      redactedTypes: redactedTypes
    }
  }
};
